served_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-048"}, {"rel": "auto_addresses_question", "node": "RQC:RQC-001"}]}, {"id": "FAM:SF-APPA-001", "label": "Study family SF-APPA-001: A1 adaptation falsification: asymmetry, confidence and carryover tests", "score": 0.892, "reached_via": ["FAM:SF-APPA-005 auto_related_family (record_link_related_to) FAM:SF-APPA-001", "FAM:SF-APPA-005 auto_related_family (limitation_precedent) FAM:SF-APPA-001"], "attributes": {"observed_research_question": "A1 adaptation falsification: asymmetry, confidence and carryover tests", "auto_outcome_status": "artifact", "observed_hypothesis": "If the A1 adapter PPP lift is real coverage response, wrong-way teams should do worse than no-signal teams, the gap should widen with scheme-vote confidence, and adapting in Game N should carry over to Game N+1.", "observed_result": "T1 dPPP: adapter +0.0667 (n=205), neutral +0.0248 (n=50), no_signal +0.1260 (n=57), wrong_way +0.0111 (n=274). T2: adapter minus no-signal -0.0361 (1 vote), -0.1170 (2 votes). T3 next-game PPP Welch t=-1.003, p=0.842; MW [cut; read_family for the full text]", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF-CHT-052", "label": "Study family SF-CHT-052: Play-type replacement similarity vs absorb/cascade", "score": 0.848, "reached_via": ["request matches RQC:RQC-133 (0.73); FAM:SF-CHT-052 auto_addresses_question RQC:RQC-133", "FAM:SF-APPA-005 auto_related_family (limitation_precedent) FAM:SF-CHT-052"], "attributes": {"observed_research_question": "Play-type replacement similarity vs absorb/cascade", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Having a similar-profile teammate separates absorption from cascade when a player sits.", "observed_result": "mean sim ABSORBED +0.863 vs CASCADE +0.848; Spearman(sim, -gap)=-0.19 (wrong-signed). Embiid 23-24 cascades with Reed sim 0.94.", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Similarity does not separate absorption from cascade; almost always findable.", "observed_sample_and_power": "NOT_RECORDED", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null", "observed_failure_type": "B_powered_null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-005"}, {"rel": "auto_related_family", "node": "FAM:SF-CHT-032"}, {"rel": "auto_related_family", "node": "FAM:SF-CHT-086"}]}, {"id": "FAM:SF-APPA-005", "label": "Study family SF-APPA-005: Defensive scheme change within game and across games (inferred labels)", "score": 0.777, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-005 (0.78)"], "attributes": {"observed_research_question": "Defensive scheme change within game and across games (inferred labels)", "auto_outcome_status": "untestable", "observed_hypothesis": "Playoff defenses change scheme within games and between games, especially after the opponent ran a play type heavily.", "observed_result": "Within-game change 319/523 (61.0%); cross-game change 298/440 (67.7%); 103/104 units (99.0%) and 52/52 series show a change; transition matrices near-uniform.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Doc caveat: inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise.", "observed_sample_and_power": "523 cells; 440 pairs", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}]}, {"id": "FAM:SF17", "label": "Study family SF17: Wiring confirmatory: persistence (P1a) and irreducibility to play-type rates (P1b)", "score": 0.76, "reached_via": ["request matches the question or hypothesis of FAM:SF17 (0.76)"], "attributes": {"observed_research_question": "Wiring confirmatory: persistence (P1a) and irreducibility to play-type rates (P1b)", "auto_outcome_status": "supported", "observed_hypothesis": "Team offensive association structure is more similar to itself across split halves than to other teams, even after residualizing play-type rates.", "observed_result": ["[APPS-080] Gate: C1 8/8 p<0.05; C2 S=0.319 perm_p=0.0002; C3 R2=0.080 PASS. Full: frobenius P1a S=0.352 p=0.0000 CI[0.327,0.378]; P1b S=0.353 CI[0.329,0.379]; cosine P1a 0.155 / P1b 0.144. residual_R2=0.043. D_obs mean=3 [cut; read_family for the full text]", "[CHT-049] Residual R^2=0.043. Frobenius P1a S=0.352 p=0.0000 CI [0.327, 0.378]; P1b S=0.353 [0.329, 0.379]. Cosine P1a S=0.155 [0.132, 0.179]; P1b S=0.144 [0.123, 0.170]. All p<0.01."], "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "[CHT-049] NOT_RECORDED"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-PAP-001"}]}, {"id": "FAM:SF-CHT-009", "label": "Study family SF-CHT-009: Superstar suppression by lineup and forced play type", "score": 0.576, "reached_via": ["request matches RQC:RQC-122 (0.73); FAM:SF-CHT-009 auto_addresses_question RQC:RQC-122", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.73); FAM:SF-CHT-009 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Superstar suppression by lineup and forced play type", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph.", "observed_result": "Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No placebo or matching; later sequence work treated similar star-chain gaps as artifacts.", "observed_sample_and_power": "n>=30 for lineup cells cited", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Jokic/Curry/Doncic/Giannis; min-15 gate on 8 play types; opposing DEFENSE_LINEUP ~84% coverage; 272-row CSV."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}, {"id": "FAM:SF-APPS-012", "label": "Study family SF-APPS-012: Defensive PPP allowed and possession share, RS vs playoffs", "score": 0.569, "reached_via": ["request matches RQC:RQC-101 (0.72); FAM:SF-APPS-012 auto_addresses_question RQC:RQC-101", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.73); FAM:SF-APPS-012 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Defensive PPP allowed and possession share, RS vs playoffs", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Playoff defenses suppress DRIVE more than RS defenses (both lower PPP allowed and lower share).", "observed_result": "DRIVE allowed 1.191 -> 0.923 (-0.268), share 21.2% -> 18.2%; PNR -0.139, share +12.1pp; PULL_UP +0.341, share -7.6pp.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No inferential test; PNR share jump of +12.1pp may reflect tagging differences.", "observed_sample_and_power": "25 teams", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "25 defensive teams, min 30 poss per cell; RS vs playoff PPP allowed and opponent possession share by PT.", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF-APPS-036", "label": "Study family SF-APPS-036: Player-level BEST vs AVOID PPP gap (initiators, 55-series)", "score": 0.511, "reached_via": ["FAM:SF-APPS-015 auto_related_family (record_link_related_to) FAM:SF-APPS-036", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.73); FAM:SF-APPS-036 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Player-level BEST vs AVOID PPP gap (initiators, 55-series)", "auto_outcome_status": "supported", "observed_hypothesis": "The team-level BEST vs AVOID gap holds when H2 possessions are filtered to initiating player.", "observed_result": "Mean gap (n>=10 each tier) +0.427 PPP. Mean BEST 1.347 (38 players) vs AVOID 0.920 (94 players). Stars mean gap +0.542 (n=15) vs role +0.428 (n=16). Only 3 players clear n>=30 both tiers (all BOS: White +0.864, Brown +0. [cut; read_family for the full text]", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "Pooled player gap +0.427 in the same direction as the team gap; most star cells are below the n>=30 gate.", "observed_sample_and_power": "38/94 players at n>=15; only 3 at n>=30 both tiers", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}], "n_results": 10}

